CREATE TABLE IF NOT EXISTS public.site_pages (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug text UNIQUE NOT NULL,
  title text NOT NULL,
  content text NOT NULL DEFAULT '',
  meta_description text,
  is_published boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.site_pages ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Anyone can view published pages" ON public.site_pages
  FOR SELECT USING (is_published = true OR has_role(auth.uid(),'admin'::app_role));

CREATE POLICY "Admins manage site pages" ON public.site_pages
  FOR ALL USING (has_role(auth.uid(),'admin'::app_role)) WITH CHECK (has_role(auth.uid(),'admin'::app_role));

CREATE TRIGGER trg_site_pages_updated BEFORE UPDATE ON public.site_pages
  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

INSERT INTO public.site_pages (slug, title, content, meta_description) VALUES
('privacy-policy', 'Privacy Policy', E'# Privacy Policy\n\n_Last updated: May 2026_\n\nKRT Jewellers ("we", "us", "our") respects your privacy. This policy explains what information we collect when you visit krtgold.lovable.app or our store at 1154, Big Bazaar Street, Coimbatore, and how we use it.\n\n## Information We Collect\n- **Account data**: name, email, phone, addresses you provide at signup or checkout.\n- **Order data**: items purchased, payment UTR / COD preference, shipping address.\n- **Usage data**: pages viewed, search queries, device info (for analytics).\n\n## How We Use It\n- Process and deliver your orders.\n- Send order, payment, and chit fund updates via email / SMS / WhatsApp.\n- Improve our products, website performance, and recommendations.\n- Comply with BIS, GST and other legal obligations.\n\n## Sharing\nWe never sell your data. We share only with: shipping partners, payment processors (UPI banks), and government authorities when legally required.\n\n## Your Rights\nYou may request access, correction, or deletion of your data by writing to **info@krtjewels.com** or calling **+91 98430 10986**.\n\n## Cookies\nWe use essential cookies for login & cart, plus Google Analytics for traffic insights. You can disable cookies in your browser.\n\n## Contact\nKRT Jewellers, 1154 Big Bazaar Street, Town Hall, Coimbatore, Tamil Nadu 641001. Email: info@krtjewels.com', 'KRT Jewellers privacy policy — how we collect, use and protect your personal data.'),
('terms-and-conditions', 'Terms & Conditions', E'# Terms & Conditions\n\n_Last updated: May 2026_\n\nBy using krtgold.lovable.app you agree to these terms.\n\n## 1. Products & Pricing\n- All gold prices are calculated **live** = (metal rate × weight) + making charges + stone cost + 3% GST.\n- Prices may change between cart and checkout if the daily gold rate changes.\n- All gold is **916 BIS Hallmarked**; diamonds are IGI / GIA certified.\n\n## 2. Orders\n- An order is confirmed only after payment is verified (UPI UTR matched) or COD is approved.\n- We reserve the right to cancel any order due to stock, pricing errors, or suspected fraud.\n\n## 3. Payments\n- We accept **Manual UPI (QR + UTR)** and **Cash on Delivery** within Tamil Nadu.\n- For COD above ₹50,000 we may request a token advance.\n\n## 4. Shipping & Delivery\n- Shipped via insured courier within 3–7 business days. See Shipping Policy.\n\n## 5. Returns & Exchange\n- 7-day exchange on unused items with original tags & invoice. See Return Policy.\n- Custom-made and engraved items are non-returnable.\n\n## 6. Intellectual Property\nAll images, designs and content belong to KRT Jewellers; reproduction without permission is prohibited.\n\n## 7. Jurisdiction\nAll disputes are subject to the courts of **Coimbatore, Tamil Nadu**.\n\n## Contact\n+91 98430 10986 · info@krtjewels.com', 'Terms and conditions for purchasing jewellery from KRT Jewellers Coimbatore.'),
('shipping-policy', 'Shipping Policy', E'# Shipping Policy\n\nWe ship pan-India through fully-insured premium courier partners (Sequel, BVC Logistics, Bluedart Secure).\n\n## Dispatch Time\n- **In-stock items**: dispatched within 24–48 hours of payment confirmation.\n- **Made-to-order / customised**: 7–15 business days.\n\n## Delivery Time\n- **Tamil Nadu**: 2–3 business days\n- **South India**: 3–4 business days\n- **Rest of India**: 4–7 business days\n\n## Charges\n- **FREE shipping** on all orders above ₹5,000.\n- ₹250 flat for orders below ₹5,000.\n\n## Insurance & Safety\n- 100% transit insurance up to invoice value.\n- Tamper-proof sealed packaging; OTP-based delivery.\n\n## Tracking\nA tracking link is sent via SMS, email and WhatsApp once dispatched. You can also track on **/track-order**.\n\n## International Orders\nCurrently we ship only within India. For overseas customers please contact our store.\n\nFor any shipping issues call **+91 98430 10986**.', 'KRT Jewellers shipping policy — insured pan-India delivery, free above ₹5,000.'),
('return-policy', 'Return & Exchange Policy', E'# Return & Exchange Policy\n\nWe want you to love every piece. If something is not right, here is how we make it right.\n\n## Eligibility\n- Return / exchange request raised within **7 days** of delivery.\n- Item is unused, unaltered, with all original tags, certificates and invoice.\n- Hallmark and packaging are intact.\n\n## Non-Returnable\n- Custom-made, engraved or resized items\n- Earrings (hygiene reasons)\n- Items damaged by misuse\n\n## Process\n1. Email **info@krtjewels.com** or call **+91 98430 10986** with order ID.\n2. Pack the item securely; we arrange a free insured pickup.\n3. Quality check at our Coimbatore store within 3–5 days.\n4. Refund / exchange / store-credit issued.\n\n## Refund Mode & Timeline\n- **UPI / bank transfer**: 5–7 business days.\n- **COD orders**: bank transfer to your provided account.\n- Making charges and GST are refunded in full for unused items.\n\n## Buy-Back / Exchange\nGold can be exchanged at the prevailing day''s rate at any time. See store for buy-back terms.', 'Return, exchange and refund policy of KRT Jewellers, Coimbatore.'),
('faq', 'Frequently Asked Questions', E'# Frequently Asked Questions\n\n## Is your gold BIS Hallmarked?\nYes. Every piece is **916 BIS Hallmarked** with HUID. Diamonds carry IGI / GIA certificates.\n\n## How is the price calculated?\n**(Live gold rate × net weight) + making charges + stone cost + 3% GST**. The live rate ticker on top of the site is what we charge.\n\n## What payment methods do you accept?\nManual UPI (scan QR & share UTR) and Cash on Delivery within Tamil Nadu. Card / EMI available in-store.\n\n## Do you offer a chit / savings scheme?\nYes — our **Sunhera Chit Fund**: pay monthly, accumulate gold grams at the day''s rate, redeem in jewellery. Visit **/chit-fund** to check your balance.\n\n## Can I exchange old gold?\nYes, at the day''s buy-back rate. Visit our Coimbatore store with the item and ID proof.\n\n## How fast is delivery?\n2–7 business days pan-India with full insurance. See Shipping Policy.\n\n## Is there a return policy?\n7-day exchange / refund on unused items with tags. See Return Policy.\n\n## Where is your store?\n**1154, Big Bazaar Street, Prakasam, Town Hall, Coimbatore, Tamil Nadu 641001.** Open Mon–Sat 10 AM – 9 PM. Call **+91 98430 10986** or **+91 422 2390505**.', 'Answers to common questions about KRT Jewellers products, payments, delivery and chit fund.')
ON CONFLICT (slug) DO NOTHING;